    ["tianjing-capital", "1853 年 3 月", "军事记录", "定都天京", "1853年3月，太平军攻克江宁（今南京），改称天京，定为都城。太平天国以此为根据地，与清政府对峙十余年，势力一度扩展到十余省，成为清朝历史上规模最大的农民战争。", ["定都天京", "南京", "1853年", "十余省", "农民战争"]],
    ["tianchao-tianmu", "1853 年", "制度文献", "天朝田亩制度", "1853年，太平天国颁布《天朝田亩制度》，提出\"有田同耕、有饭同食、有衣同穿、有钱同使\"的社会理想，主张按人口平分土地。但这一方案超越现实条件，实际并未真正实施，反映了农民起义的空想性。", ["天朝田亩制度", "有田同耕", "平分土地", "空想性", "未实施"]]
