    people: [["闽南水手", "中国商人", "约翰·塞尔登", "英国学者", "明朝官员"], "从绘制地图的闽南水手到收藏它的英国学者，这幅地图经历了怎样的流转？不同的人对它的理解有什么不同？"],
    process: [["航海经验积累", "绘制海图", "贸易往来", "流入英国", "重新发现"], "从闽南水手的航海实践到地图被英国学术界重新认识，这幅地图经历了怎样的传播过程？"],
    ending: [["海洋中心视角", "贸易网络", "航线标注", "中西交流", "知识传播"], "《塞尔登中国地图》揭示了明清时期怎样的海洋贸易网络？它与其他中国古地图有什么不同？"],
    limits: [["官方海禁", "民间贸易", "知识流失", "长期忽视", "认知差异"], "为什么这幅以海洋为中心的中国地图会被长期忽视？明清官方海洋政策与民间航海实践之间存在什么矛盾？"],
